def process(stage0_load) -> pd.DataFrame:
    df = stage0_load.copy()
    for c in ['SepalLengthCm', 'SepalWidthCm', 'PetalLengthCm', 'PetalWidthCm']:
        df[c + '_z'] = (df[c] - df[c].mean()) / df[c].std()
    return df

def process(stage3_filter) -> pd.DataFrame:
    return stage3_filter.groupby('Species').agg(
        count=('Id', 'count'),
        mean_petal_area=('petal_area', 'mean'),
        mean_sepal_area=('sepal_area', 'mean'),
        mean_ratio=('petal_to_sepal_ratio', 'mean')
    ).reset_index()
